CREATE SET TABLE MDP01_META.META_AREA_CATEGORY ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      area_category_id INTEGER NOT NULL,      area_category_name VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      area_category_code VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      layer_id INTEGER NOT NULL,      beschreibung VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( area_category_id )UNIQUE INDEX ( area_category_code );